try {
  checkpointText = await readFile(checkpointPath, 'utf8');
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
}
if (checkpointText !== undefined) {
  try {
    ({ nextLine } = JSON.parse(checkpointText));
    if (!Number.isSafeInteger(nextLine) || nextLine < 0) throw new Error('Invalid checkpoint nextLine');
  } catch {
    const recoveryDirectory = join(dirname(checkpointPath), 'recovery');
    await mkdir(recoveryDirectory, { recursive: true });
    // An exclusive link preserves the exact bytes without overwriting prior
    // recovery evidence. Only remove the original after preservation succeeds.
    await link(checkpointPath, join(recoveryDirectory, 'checkpoint.bad.json'));
    await unlink(checkpointPath);
    nextLine = 0;
  }
}

